export function findDivision(slug:string){ return expertise.find(x=>x.slug===slug); }
export function findService(division:string, service:string){return findDivision(division)?.services.find(x=>x.slug===service);}
export function allExpertisePaths(){return expertise.flatMap(d=>d.services.map(s=>({division:d.slug,service:s.slug})));}


